python3 -c "
try:
    import numpy as np, csv
    rows=list(csv.DictReader(open('data/sales.csv')))
    r=np.array([int(x['units'])*float(x['unit_price']) for x in rows])
    print('numpy median:',repr(np.median(r)),'round:',np.round(np.median(r),2))
except ImportError: print('no numpy')
try:
    import pandas as pd
    d=pd.read_csv('data/sales.csv'); rev=d.units*d.unit_price
    print('pandas median round:',round(rev.median(),2))
except ImportError: print('no pandas')
"
